'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=file=>fs.readFileSync(path.join(root,file),'utf8');
const selector=read('docs/scifi-ui/scripts/formatx-reference-core-v26.js');
const productionBootstrap=read('docs/scifi-ui/scripts/formatx-core-real3d-v20.js');
const reference=read('docs/scifi-ui/scripts/formatx-reference-lock-v30.js');
const webgpu=read('docs/scifi-ui/scripts/formatx-webgpu-core-v29.js');
const webgl=read('docs/scifi-ui/scripts/formatx-orbital-core-v28.js');
const cinematic=read('docs/scifi-ui/scripts/formatx-cinematic-core-v27.js');
const entry=read('billing-worker/src/production-entry.js');

assert.match(selector,/const WEBGPU_PREVIEW = params\.get\('webgpu'\) === '1'/,'WebGPU preview must be explicit opt-in');
assert.match(selector,/production-v30-reference-lock-authority/,'v30 must remain production authority');
assert.match(selector,/webgl2-v30-uploaded-reference-production/,'v30 production GPU marker missing');
assert.match(productionBootstrap,/formatx-reference-lock-v30\.js\?v=20260810-uploaded-reference-lock-\d+/,'cache-busted production renderer missing');
assert.match(productionBootstrap,/formatx-reference-lock-v30\.css\?v=20260810-uploaded-reference-lock-\d+/,'cache-busted production style missing');
assert.match(reference,/glass-dominant-sparse-veins-r4/,'r4 glass surface state missing');
assert.match(reference,/mesh\(shell,mul\(B,sc\(\.998,\.998,\.998\)\),1,\.30/,'dominant cyan glass surface missing');
assert.match(reference,/for\(const k of\[2,4,6,8,10,R\]\)/,'sparse reference veins missing');
assert.ok(reference.includes('ready-v30'),'production reference ready marker missing');
assert.doesNotMatch(selector,/if \(navigator\.gpu\)[\s\S]{0,500}webgpu-primary/,'WebGPU must not automatically replace production MAG');
assert.match(webgpu,/navigator\.gpu\.requestAdapter/,'WebGPU preview adapter request missing');
assert.match(webgpu,/pass\.drawIndexed/,'WebGPU preview indexed drawing missing');
assert.match(webgl,/canvas\.getContext\('webgl2'/,'WebGL2 preview fallback missing');
assert.match(webgl,/gl\.drawElements\(gl\.TRIANGLES/,'WebGL2 preview indexed drawing missing');
assert.match(cinematic,/retired-by-orbital-v28/,'legacy cinematic overlay must remain retired');
assert.match(entry,/formatx-reference-core-v26\.js/,'production selector injection missing');
assert.doesNotMatch(reference,/new\s+Image\s*\(|drawImage\s*\(|THREE\b|three\.js/i,'production reference MAG cannot be image-backed or Three.js-backed');
console.log('PASS: glass-dominant sparse-vein v30 remains the production authority; WebGPU v29 and WebGL2 v28 remain opt-in preview paths.');
